const player=id=>PLAYERS.find(p=>p.id===id);
const teamName=team=>team==='harbor'?'Harbor FC':'Northbridge';
const eventTeam=e=>e.outcome==='intercepted'?player(e.interceptor)?.team:e.type==='tackle'?player(e.from)?.team:e.team;
const involved=(e,id)=>e.from===id||e.to===id||e.interceptor===id;
const number=(n,language)=>new Intl.NumberFormat(language,{maximumFractionDigits:1}).format(n);
